B.aUa=new A.b5("\u0627\u0644\u0625\u062f\u063a\u0627\u0645 \u0628\u063a\u064f\u0646\u0651\u0629","\u0627\u0644\u0646\u0648\u0646 \u0627\u0644\u0633\u0627\u0643\u0646\u0629 \u0623\u0648 \u0627\u0644\u062a\u0646\u0648\u064a\u0646 \u0642\u0628\u0644 \u062d\u0631\u0648\u0641 (\u064a \u0646 \u0645 \u0648) \u062a\u064f\u062f\u063a\u0645 \u0641\u064a \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u062a\u0627\u0644\u064a \u0645\u0639 \u063a\u064f\u0646\u0651\u0629.","\u0644\u0627 \u062a\u0646\u0637\u0642 \u0627\u0644\u0646\u0648\u0646\u061b \u0627\u062f\u062e\u0644 \u0641\u064a \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u062a\u0627\u0644\u064a \u0645\u0628\u0627\u0634\u0631\u0629 \u0645\u0639 \u0627\u0644\u063a\u0646\u0629.")
B.aUl=new A.b5("Idgham with ghunnah (merging)","A noon with sukoon or tanween before yaa, noon, meem or waw merges into it, with ghunnah.","Don't say the noon; go straight into the next letter with the nasal sound.")
