B.aUO=new A.b5("\u0627\u0644\u0644\u0627\u0645 \u0627\u0644\u0634\u0645\u0633\u064a\u0629","\u0644\u0627\u0645 \xab\u0627\u0644\xbb \u0642\u0628\u0644 \u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0634\u0645\u0633\u064a\u0629 \u0644\u0627 \u062a\u064f\u0646\u0637\u0642\u060c \u0648\u064a\u064f\u0634\u062f\u064e\u0651\u062f \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u0630\u064a \u0628\u0639\u062f\u0647\u0627.","\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u0644\u0627\u0645 \u0648\u0627\u0646\u0637\u0642 \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u062a\u0627\u0644\u064a \u0645\u0634\u062f\u062f\u0627\u064b.")
B.aVg=new A.b5("Laam shamsiyyah (silent laam)",'The laam of "al" before a sun letter is silent, and the next letter is doubled.',"Skip the laam and say the next letter doubled.")
B.aUt=new A.b5("\u0644\u0627\u0645\u0650 \u0634\u0645\u0633\u06cc","\xab\u0627\u0644\xbb \u06a9\u0627 \u0644\u0627\u0645 \u062d\u0631\u0648\u0641\u0650 \u0634\u0645\u0633\u06cc\u06c1 \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u0646\u06c1\u06cc\u06ba \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627\u060c \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u0628\u0639\u062f \u0648\u0627\u0644\u0627 \u062d\u0631\u0641 \u0645\u0634\u062f\u0651\u062f \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4","\u0644\u0627\u0645 \u0686\u06be\u0648\u0691 \u062f\u06cc\u06ba \u0627\u0648\u0631 \u0627\u06af\u0644\u0627 \u062d\u0631\u0641 \u0645\u0634\u062f\u0651\u062f \u067e\u0691\u06be\u06cc\u06ba\u06d4")
B.aV3=new A.b5("Alif Lam Syamsiyah","Lam pada \xabal\xbb sebelum huruf syamsiyah tidak dibaca, dan huruf sesudahnya dibaca bertasydid.","Lewati lam-nya dan baca huruf berikutnya dengan tasydid.")
B.aVj=new A.b5("Lam solaire (lam muet)","Le lam de \xab al \xbb devant une lettre solaire ne se prononce pas, et la lettre suivante est redoubl\xe9e.","Sautez le lam et dites la lettre suivante redoubl\xe9e.")
B.aU7=new A.b5("\u09b2\u09be\u09ae \u09b6\u09be\u09ae\u09b8\u09bf\u09af\u09bc\u09cd\u09af\u09be\u09b9 (\u09a8\u09c0\u09b0\u09ac \u09b2\u09be\u09ae)","\xab\u0986\u09b2\xbb-\u098f\u09b0 \u09b2\u09be\u09ae \u09b6\u09be\u09ae\u09b8\u09c0 \u09b9\u09b0\u09ab\u09c7\u09b0 \u0986\u0997\u09c7 \u0989\u099a\u09cd\u099a\u09be\u09b0\u09bf\u09a4 \u09b9\u09af\u09bc \u09a8\u09be, \u0986\u09b0 \u09aa\u09b0\u09c7\u09b0 \u09b9\u09b0\u09ab\u099f\u09bf \u09a4\u09be\u09b6\u09a6\u09c0\u09a6 \u09b8\u09b9 \u09aa\u09a1\u09bc\u09be \u09b9\u09af\u09bc\u0964","\u09b2\u09be\u09ae \u09ac\u09be\u09a6 \u09a6\u09bf\u09af\u09bc\u09c7 \u09aa\u09b0\u09c7\u09b0 \u09b9\u09b0\u09ab\u099f\u09bf \u09a4\u09be\u09b6\u09a6\u09c0\u09a6 \u09b8\u09b9 \u09aa\u09a1\u09bc\u09c1\u09a8\u0964")
